@Transactional
public void processOrder(Order order) {
    // Local transaction for inventory
    inventoryService.reserve(order.getItems());
    try {
        // Remote call via NIO-based client
        paymentService.charge(order.getAmount());
    } catch (Exception e) {
        // Compensating transaction to restore consistency
        inventoryService.release(order.getItems());
        throw new DistributedTransactionException("Payment failed, rolling back inventory");
    }
}
